cards=[]
cards.append(compact('jia_yuzhen','贾玉珍','贾玉珍早年在古董行做学徒，凭眼力迅速赢得声誉，也养成了压价、摆架子和处处计算得失的商人脾气。面对鲁尔家传的古玉，他比旁人更快看出其中秘密，追索的目标却逐渐从古董价值变成求仙之路。他获得仙箓和九颗玉真天露丹，按法练气服药，外貌和身体明显返老还童，最后在神秘所在继续修炼。卫斯理原想用抗衰老素和人体潜能解释，贾玉珍却只肯用仙缘、仙丹和仙法说话；两人争论既有知识差异，也有他得意后不愿承认自己尚不理解的虚荣。他能将师长教的话背出来，说明空间转移和聚集环境能量，却又亲口承认自己还没有那些本领。终局他仍须修炼近百年，卫斯理再未见他，不能把将来的预期成就当作已经掌握的时间旅行或点石成金。卡片保留鉴定能力、已经发生的身体变化以及不改旧性的小心眼，使他既可帮助熟人，又会在被追问原理时恼羞，不因成仙便成为超然无欲的说明书。','《神仙》返老还童后留在仙境继续长期修炼，后续成就未证实','主角','延续生命、守住难得仙缘，同时保留被人承认眼力的自尊','鉴古认真而交易精明，讲仙法时偏爱熟悉的传统词语','被质疑时摆架子，真正讲不清则向师长请教后转述','已经做到的身体变化与未来可能学会的空间能力必须分开',[ab('古物鉴定','多年实践识别古玉及古物价值，发现线索后追索来源','有商人私心，鉴定能力不能自动破解所有外星物品'),ab('服丹练气后的返老还童','实际服完九颗玉真天露丹并按仙箓修习，身体恢复年轻','丹药已经用尽；没有证实此时能为别人返老还童，寿命上限未实测')],[ev('059',25,63,'古董经历与性格'),ev('059',1847,1866,'仙箓和九丹'),ev('059',2019,2050,'修习与返老还童'),ev('059',3494,3499,'明确未掌握环境聚能'),ev('059',3645,3683,'仍须长期修习及失联')],profile='expert'))
rate(cards[-1],[1,0,1,9,1,1],tier='并',reason='只计已实现返老还童与鉴定知识；未获得空间转移、元素改变及时间旅行。')
cards[-1]['baseline']['stamina']='身体已返老还童，日后寿命和持续活动时长未实测；长期修炼不能换算成无限战斗续航。'
cards.append(compact('hu_shi','胡士','胡士是东欧情报体系的中校，处在能够监视、拘禁和审问他人的位置，对古玉牵出的抗衰老秘密抱有强烈兴趣。他掌握鲁尔和贾玉珍的行踪，把卫斯理拖入审讯，既用长年牢狱相威胁，也试图通过窃听得到秘密。卫斯理为了脱身，编造古玉是黄帝信符的说法，又利用胡士希望离开现有生活的欲望，以巨额报酬提出交易。胡士并非听见科学词汇便完全理解，他的判断在职务利益、个人恐惧和财富诱惑之间转动，最后帮助脱逃并取得支票，去瑞士整容隐姓。这个结果不能抹掉他曾以公权拘押无辜者的责任，也不能把最后背离组织写成从头便有的侠义。他没有获得真正的仙丹、抗衰老方法或信符力量，失去官方身份后也不能随时调用原机构的监狱和人员。终局卡保留监视审讯的经验、趋利避险的聪明与曾被故事欺骗的边界；新的诱惑出现时，他应检查兑现方式，却仍可能把可以想象的富裕生活放在职责之前。','《神仙》取得报酬后赴瑞士整容脱离旧身份，卫斯理再无法找到','反派','摆脱受制于组织的生活并获得个人安全与财富','善用监视、窃听和官僚压力搜集信息','利益受威胁时以拘禁恫吓，遇更可取的出路又愿背离职责','威胁有效不等于掌握真相，秘密交易须留意对方可能在编造',[ab('情报审讯','有监控、窃听、扣押与施压经验','机构资源须实际可用；终局叛逃后不默认继续指挥旧部'),ab('秘密交易与脱身','能够评估金钱条件并协助逃离，利用整容掩盖身份','不是绝对隐形或无法追踪；古玉故事实为卫斯理的欺骗')],[ev('059',893,923,'情报身份与调查'),ev('059',1365,1408,'威胁及审讯'),ev('059',1530,1568,'窃听和金钱交易'),ev('059',2208,2234,'整容出走计划'),ev('059',3683,3683,'终局失联')],profile='investigator',aliases=['胡士中校']))
cards.append(compact('lu_er','鲁尔','鲁尔生活在东柏林，继承了祖父留下的古玉和含混遗训，知道家族把它当作重要财物，却缺少足够知识判断价值。他写信向卫斯理求助，原本期待的是鉴定和解决家庭遗产之谜，没想到古玉会牵出掠夺历史、古董商和秘密机关。祖父当年从中国夺走玉件及宝盒，留下的是暴力所得与未解线索，不能由继承人的无知便说成合法探险的奖品。鲁尔本人在事件中被情报机关控制，成为胡士逼问秘密的一环；他知道的有限，这种有限又不被掌握权力的人相信。卫斯理和胡士后来离开时，鲁尔仍在拘押中，文本没有交代确定获释，卡片应保留这一不圆满结局，而不能为方便演绎擅自补上团圆。鲁尔没有祖父的军人经历，没有古玉开启后所联系的神仙本领，更没有因为家传物件而获得抗衰老能力。他可以携带对家族记忆的复杂态度，在有机会行动时寻求可信的鉴定和实际援助；遭到逼问时承认不知道，比凭空补出藏宝图和神秘学传承更符合这个普通人的处境。','《神仙》卫斯理等离开时仍遭拘押，是否随后获释未交代；部署须说明行动自由是场景条件','主角','弄清祖传古玉并恢复正常生活','以书信和家族记录寻求专业鉴定','被拘押逼问时承受恐惧，所知不足以满足机关期待','祖传物的秘密不能凭继承身份自动获知',[ab('家族线索保存','提供祖传玉件及祖父留下的资料，连接事件历史','不具备玉件关联仙法；线索含祖辈掠夺行为与认知局限')],[ev('059',7,22,'来信和东柏林生活'),ev('059',1679,1739,'祖父记述及拘押未解')],profile='ordinary'))
cards.append(compact('lu_er_grandfather','老鲁尔少尉','老鲁尔是鲁尔的祖父，在一九〇〇年作为德国少尉参与八国联军侵华。他留下的记述不是一个中立寻宝者的游记，而是武装优势如何转成抢劫的自证：看见保护告示仍撕毁，用枪打开门户，以孩子作人质，迫使主人交出收藏。宝盒后来在德国卖出，玉件因没有人认得价值而留在家中，最终成为后代求鉴和遭遇危险的来源。他有军人的枪械和威吓经验，也有面对陌生文化时把复杂器物直接看成财富的浅薄；没有读懂玉的用途，并未在抢到它后成为仙人。历史中的暴力可以通过遗产、记忆和受害者的物证继续影响后人，不能因此算成他死后主动施法或支配家族。终局卡按已故历史人物处理，若要参演则明确恢复最后可行动的生前形态，保留作为侵略者的责任而不替他补造悔悟。他面对新地方可能继续用军衔、武器和强制要求打开道路；真正超出其经验的现象会使他困惑，权力并不保证理解。','历史已故；部署恢复最后可行动的生前军人形态，不复活完整侵略军或返还已失宝物','反派','利用军队优势掠取财物并把所得带回本国','以军人身份行动，重视可搬走和可以出售的战利品','遇到阻拦以枪械和人质胁迫，不尊重保护告示','暴力夺得物品不等于掌握其用途，未知技术仍会超出经验',[ab('常规枪械与胁迫','以军用枪械破门并挟持人质，借武装身份实施掠夺','只具常规军人能力；部队须另行存在，玉件未授予神通')],[ev('059',1679,1685,'历史军人身份'),ev('059',1699,1729,'撕告示、破门挟持和后来处置')],profile='investigator'))
cards.append(compact('immortal_master','石屏风后的神仙','石屏风后的神仙是贾玉珍修行所在的隐居者，据贾转述在东汉末年已经得道，长久不愿见普通访客。他没有为满足卫斯理的好奇而现身，也没有把每次追问当作必须服从的命令；当卫斯理试图绕到屏风后，他使有限空间反向转移，让人走、跑、扑跃都不能真正接近。与此同时，他又愿意教贾玉珍用现代措辞解释这些现象，说明拒绝露面与完全敌视交流并非一回事。叙述将其方法解释为聚集环境能量和空间转移，并由此谈到时间旅行与元素改变，但后两者没有在这个人身上逐项展示，不能仅据“神仙”两字无限外推。最后他将卫斯理送回原处，保护自己的居所和秩序而没有直接杀伤访客。卡片保留长寿、稳定局部空间干预以及有限度的教学态度，服丹与仙法的最初来源仍不明。演绎中他可以用距离和通行条件表达边界，也可以因诚恳的问题多说一句；不必总在云雾里宣告玄理，更不能把人物们的“无所不能”赞叹变成作者授予的绝对权能。','《神仙》仍隐居于位置未明的修行空间，以空间手段送卫斯理离开','主角','保持隐居秩序并在愿意的范围内传授修行知识','不轻易露面，以短语和弟子的转述沟通','有人越过通行边界时改变局部空间关系阻止接近','说明机制可以选择对方能懂的语言，长期修行不等于全知',[ab('局部空间转移','使访客前进时空间反向移动，阻止接近屏风，后来将卫斯理转送回去','确证的是现场阻隔与送离；未展示全宇宙覆盖、任意时间改写或对所有敌人的必胜'),ab('环境能量运用与长寿','据转述通过身体汇集周围能量支持仙法，身份延续至东汉末年','具体能源上限、离开居所的条件及受伤抗性不明；时间旅行和炼金仅解释性谈论')],[ev('059',3395,3459,'真实阻隔与隐居态度'),ev('059',3468,3499,'空间机制和环境能源解释'),ev('059',3628,3635,'送回卫斯理及身份语言')],profile='expert',aliases=['东汉末年得道者']))
rate(cards[-1],[0,6,4,8,8,4],tier='狂',reason='以已展示局部空间阻隔、转送与长期生存计分；不将解释性的时间旅行和元素改变扩大为绝对权柄。',mastery='完全掌握')
cards[-1]['baseline'].update({'durability':'可阻止访客接近，但肉身直接抗击、抗毒及受伤恢复未展示；不能将空间防护当成无敌身体。','speed':'空间阻隔和转送可绕过一般步行距离，未给出固定速度或全宇宙瞬移范围。','energy':'能够汇集环境能量施行已展示仙法；数值与最大范围不明。','stamina':'长寿有文本说明，连续空间干预的极限未给出，非无限战斗续航。'})
cards.append(compact('immortal_child','小神仙','小神仙是在贾玉珍修行所在一闪而过的小孩形人物，卫斯理先看见细小身影，后来才从贾玉珍口中知道对方具有特殊能力。最明确的行动并不是庄严传法，而是因为顽皮去动卫斯理携带的炸药引爆器，几乎惹出祸事。这种行为让故事强调得到超常能力后性格未必随之变得成熟，也使他成为现场风险的实际来源。小神仙怎样来到这里、修炼多久、与屏风后长者是什么关系，都没有得到具体交代；贾玉珍猜想孩子也同样服丹练箓，不等于已经取得一份可靠身世档案。卡片因此只保留可见的快速出入、对陌生器物的好奇和容易低估后果的孩子气，不把成人神仙介绍的全部空间、时间和炼金本领自动分配给他。终局仍在神秘修行处，没有证实离开、死亡或成长后的状态。演绎可让他在禁止触碰与想知道如何运作之间犹豫，犯错后面对他人反应，而不能让“神仙”成为任何恶作剧都安全无害的保证，也不必机械重复炸药事件才能显出顽皮。','《神仙》仍为修行处的小孩形神仙，具体年龄、来历与能力上限不明','阶段性对立者','满足好奇、试探陌生器物和周围人的反应','动作轻快而顽皮，容易先碰再问','玩耍酿险时需要面对实际后果，不能假定自己总能补救','拥有特殊经历不等于成熟，危险器物的功能须先确认',[ab('迅速接近与器物干预','曾以细小身影闪现并动过引爆器','只有这次现场行动得到确认；不赋予成人神仙的全部空间时间技能')],[ev('059',3510,3519,'身影、干预和顽皮性质'),ev('059',3520,3535,'对成仙来源的讨论未解')],profile='ordinary'))
rate(cards[-1],[2,0,1,4,2,3],tier='并',reason='仅按快速器物干预和非普通修行状态保守计分；未知仙法不能作已掌握战力。')
cards[-1]['uncertainties'].append('年龄、寿命、身体抗性与具体仙法均未详述；数值置信度低。')
cards.append(compact('kong_zhenquan','孔振泉','孔振泉是九十余岁的星相研究者，一生记录天象及相应事件，临终前却被自己看见的灾难征兆折磨。他要求找到卫斯理，希望这个常涉奇事的人能阻止东方大城面临的惨祸；卫斯理最初不懂他的术语，答不上问题，便被他斥为冒牌，白素用四川话安抚才稍缓和。衰弱的老人仰望星空，指出七宿异色星芒，情急时挣起身体伸手向天，仿佛想把压来的灾难顶住，最后在呼喊中死去。留下的星图、记录和隐藏信息让卫斯理与陈长青继续追索，但他们逐渐认识到，观察出趋势与有力量改变事件是两种完全不同的事。孔振泉从来没有成功改变天象所预示的事件，不能因所预言的规模巨大就算有毁城或控星能力。终局卡以最后生前的衰弱状态参演，保留他的记录知识、恻隐和急躁，不自动赋予任何未来的确定答案。他面对风险会急于推动警示，也可能因听者不懂而失去耐心；可演的核心是知道得比别人早，却仍要寻找有限的人力如何减少伤害。','《追龙》预警途中死亡；部署恢复最后生前的高龄衰弱形态，保留记录知识而非全能预言','主角','在有生之年让别人听懂灾难警告，尽可能挽救生灵','长年细察星象并保存记录，使用专门术语','预见惨祸时急切甚至暴怒，不顾身体衰弱也要催人行动','预知事件不等于能操控事件，更不能以预言规模代替自身战力',[ab('星象记录与灾兆辨认','长期观察并整理星图，从特定星芒推断事件趋势','预示的解释和具体实现仍有不确定；没有任意读取个人未来或改变天体的证据'),ab('隐含信息保存','用星图、器物和记录保留线索供后来者追索','接手者须解释资料，不能直接获得他的全部知识')],[ev('060',250,295,'临终求助和性格'),ev('060',820,877,'观象、忧患与死亡'),ev('060',1600,1679,'记录被解释及灾难推测'),ev('060',3172,3195,'始终只有观察而未改变')],profile='expert'))
