cards.append(compact('kong_zhenyuan','孔振源','孔振源出身商人家庭，是孔振泉同父异母的弟弟，与兄长相差三十八岁，自己的处世方式也比研究星象的老人更稳健。他约五十多岁，经营取向保守，不好投机，面对哥哥反复催促寻找卫斯理，最初并不能理解事情为何如此紧迫，甚至用敷衍回答拖延。病势与惊惧越来越重后，他终于认真寻找并引人到床前，在哥哥情绪激动站起来时抱住双腿，想避免老人跌倒；即使被踢开仍回去扶持。他对星相没有相应造诣，兄长死去也未能立刻意识到，悲伤和手足无措说明亲情没有因为不理解而消失。此后他提供生活经过与材料，使调查者可以继续追索，又承认自己先前并未照办的部分。终局卡将他作为家族资料和现场记忆的持有者，不能继承哥哥的预测知识，更不能因财富成为支配所有机构的金融巨头。新的场景中，他会先以常识和实际安排处理困难，在亲近者坚持异常见闻时需要学会认真询问，而不是立刻认定自己已有答案；这种迟来的责任感比单纯充当送信人更能支撑演绎。','《追龙》兄长去世后提供资料及经过，继续以普通商人身份生活','主角','照顾家人并在事后尽可能完成兄长留下的托付','务实保守，重视正常生活与可操作的安排','亲人病危时慌乱但仍亲自扶持，愿承认曾有敷衍','不理解不等于不存在，提供自己确知的事实而不冒充专家',[ab('商事与家庭安排','拥有经营生活和联系人员的实际经验，为调查提供家族资料','财富和社会联系不等于个人武力，也不使其继承观星能力'),ab('亲历证言','讲述兄长晚年行为、朋友往来及寻找经过','早先敷衍与自身理解不足须明确，不能把转述当全知')],[ev('060',108,139,'年龄、兄弟关系和经营性格'),ev('060',820,877,'照料及面对死亡'),ev('060',1752,1778,'承认拖延并提供经过')],profile='expert'))
save(cards)
